import { z } from 'zod';
import pins from './pins.json';

/**
 * The add-ons this build needs, generated by `scripts/build-addons.mjs`.
 *
 * Each entry names the **content identity** of the add-on the build was made
 * against (a digest of its sources, not a hand-written version) and the
 * `apiVersion` it expects. A published catalogue may hold many identities at
 * once, and an installed add-on of another identity is never used - the pinned
 * one is downloaded and the older one deleted.
 */

export const addonPinsSchema = z.record(
  z.string().regex(/^[a-z][a-z0-9-]{0,63}$/),
  z
    .object({
      identity: z.string().regex(/^[0-9a-f]{16}$/),
      apiVersion: z.number().int().positive(),
    })
    .strict(),
);

export type AddonPins = z.infer<typeof addonPinsSchema>;

export interface AddonPin {
  readonly identity: string;
  readonly apiVersion: number;
}

/**
 * The pins this build ships. Parsed once, at module load: a malformed generated
 * file is a build fault and must fail loudly rather than silently install
 * nothing.
 */
export const addonPins: AddonPins = addonPinsSchema.parse(pins);

export function pinFor(id: string): AddonPin | undefined {
  return addonPins[id];
}
